'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');

let pos = 0;
function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

function readTree(size) {
  const graph = Array.from({ length: size }, () => []);
  for (let i = 1; i < size; i++) {
    const a = nextInt() - 1;
    const b = nextInt() - 1;
    graph[a].push(b);
    graph[b].push(a);
  }
  return graph;
}

function bfs(graph, start) {
  const n = graph.length;
  const dist = new Int32Array(n);
  dist.fill(-1);
  const queue = new Int32Array(n);
  let head = 0;
  let tail = 0;
  queue[tail++] = start;
  dist[start] = 0;
  let farthest = start;

  while (head < tail) {
    const node = queue[head++];
    if (dist[node] > dist[farthest]) farthest = node;
    for (const next of graph[node]) {
      if (dist[next] === -1) {
        dist[next] = dist[node] + 1;
        queue[tail++] = next;
      }
    }
  }
  return { dist, farthest };
}

function findCenter(graph) {
  const endpointA = bfs(graph, 0).farthest;
  const fromA = bfs(graph, endpointA);
  const fromB = bfs(graph, fromA.farthest);

  let center = 0;
  let bestEccentricity = Infinity;
  for (let i = 0; i < graph.length; i++) {
    const eccentricity = Math.max(fromA.dist[i], fromB.dist[i]);
    if (eccentricity < bestEccentricity) {
      bestEccentricity = eccentricity;
      center = i;
    }
  }
  return center;
}

const n = nextInt();
const m = nextInt();
const circle = readTree(n);
const square = readTree(m);

console.log(`${findCenter(circle) + 1} ${findCenter(square) + 1}`);
